        ConverseStreamOutput::MessageStart(_) => {}
        ConverseStreamOutput::ContentBlockStop(_) => {}

        // ── content block start ───────────────────────────────────────────
        ConverseStreamOutput::ContentBlockStart(e) => {
            let idx = e.content_block_index();
