            }
        }

        // ── metadata (usage) ──────────────────────────────────────────────
        ConverseStreamOutput::Metadata(e) => {
            self.metadata_seen = true;
            if let Some(usage) = e.usage() {
                out.push(Ok(ModelEvent::Usage {
                    input_tokens: usage.input_tokens().max(0) as u32,
                    output_tokens: usage.output_tokens().max(0) as u32,
